    s = list(s)
    zeros = []
    for i in range(n):
        if s[i] == '0':
            zeros.append(i)

    result = ['1'] * n
    zero_index = 0
    moves_used = 0

    for i in range(n):
        if s[i] == '0':
            continue

        while zero_index < len(zeros) and moves_used + (zeros[zero_index] - i) <= k:
            moves_used += zeros[zero_index] - i
            result[zeros[zero_index]] = '1'
            zero_index += 1

        if zero_index < len(zeros):
            result[i] = '0'
        else:
            break

    return ''.join(result)

